#!/usr/bin/env python3
"""lifeplus-admin-icon-v2:
  ・予約管理（https://lifeplusllc.com/admin/）を iPhone のホーム画面に置いたときのアイコン
    すりガラスのカレンダーと白いチェック（後ろに会社のオレンジ・緑と青の光）
  ・ホーム画面の名前は「予約管理」
  ・docs/admin/icon-180.png（iPhone）・icon-512.png・icon-32.png（ブラウザのタブ）を置く
  ★patch_lifeplus_admin_icon_v1.py を流していてもいなくても、これだけ流せばよい
何度流しても同じ結果になる。直す前に .bak_admin_icon_v2 を残す。
"""
import base64, os, shutil
MARK = "lifeplus-admin-icon-v2"
HERE = os.path.dirname(os.path.abspath(__file__))
IMGS = {'docs/admin/icon-512.png': '', 'docs/admin/icon-180.png': '', 'docs/admin/icon-32.png': ''}
for rel, b64 in IMGS.items():
    p = os.path.join(HERE, rel)
    data = base64.b64decode(b64)
    if not os.path.exists(p) or open(p, "rb").read() != data:
        open(p, "wb").write(data); print("置いた", rel)
    else:
        print("済み", rel)
p = os.path.join(HERE, "docs", "admin", "index.html")
s = open(p, encoding="utf-8").read()
ANCHOR = '  <title>予約管理｜LIFE PLUS</title>\n'
BLOCK = ('  <!-- ' + MARK + ' -->\n'
         '  <link rel="icon" href="icon-32.png?v=2" sizes="32x32">\n'
         '  <link rel="apple-touch-icon" href="icon-180.png?v=2">\n'
         '  <meta name="apple-mobile-web-app-title" content="予約管理">\n'
         '  <meta name="theme-color" content="#101735">\n')
OLD_V1 = ('  <!-- lifeplus-admin-icon-v1 -->\n'
          '  <link rel="icon" href="icon-32.png?v=1" sizes="32x32">\n'
          '  <link rel="apple-touch-icon" href="icon-180.png?v=1">\n'
          '  <meta name="apple-mobile-web-app-title" content="予約管理">\n'
          '  <meta name="theme-color" content="#1d4ed8">\n')
if MARK in s:
    print("済み docs/admin/index.html")
else:
    assert s.count(ANCHOR) == 1, "予約管理の title の所が想定と違います"
    shutil.copyfile(p, p + ".bak_admin_icon_v2")
    if OLD_V1 in s:
        s = s.replace(OLD_V1, BLOCK)
    else:
        assert "lifeplus-admin-icon-v1" not in s, "前のアイコンの所が想定と違います"
        s = s.replace(ANCHOR, ANCHOR + BLOCK)
    open(p, "w", encoding="utf-8").write(s)
    print("直した docs/admin/index.html")
s = open(p, encoding="utf-8").read()
assert MARK in s and "icon-180.png?v=1" not in s and s.count("apple-touch-icon") == 1
for rel in IMGS: assert open(os.path.join(HERE, rel), "rb").read() == base64.b64decode(IMGS[rel]), rel
print("OK: 予約管理のアイコン（すりガラス）を入れました（" + MARK + "）")
